from pathlib import Path
from html import escape
import json
root=Path(__file__).resolve().parent
manifest=json.loads((root/'manifest.json').read_text())
groups={}
for v in manifest['newViews']: groups.setdefault(v['group'],[]).append(v)
css='''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#f7f7f5;color:#252523;font:15px/1.55 -apple-system,BlinkMacSystemFont,"Segoe UI",Arial,sans-serif}header,main,footer{max-width:1320px;margin:auto;padding:32px}header{padding-top:48px}h1{font-size:36px;line-height:1.15;letter-spacing:-1px;font-weight:600;margin:12px 0 16px}h2{font-size:24px;font-weight:600;margin:0 0 6px}h3{font-size:16px;line-height:1.4;font-weight:600;margin:0}p{margin:8px 0;color:#646461;max-width:940px}a{color:#7a1f1f;text-underline-offset:4px}a:focus-visible{outline:2px solid #7a1f1f;outline-offset:4px}.eyebrow{font-weight:600;color:#7a1f1f}.facts{display:flex;gap:8px;flex-wrap:wrap;margin:20px 0}.facts span{background:#fff;border:1px solid #e2e2e0;border-radius:4px;padding:6px 10px;color:#646461;font-size:13px}nav{display:flex;flex-wrap:wrap;gap:8px;margin-top:24px}nav a{display:flex;min-height:48px;align-items:center;padding:10px 14px;border:1px solid #e2e2e0;border-radius:12px;text-decoration:none;background:#fff;font-weight:500}main{padding-top:0}.group{padding:32px 0 40px;border-top:1px solid #e2e2e0;scroll-margin-top:20px}.group>p{font-size:14px;margin-bottom:24px}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:32px 24px}figure{margin:0;min-width:0}.phone{display:block;width:100%;max-width:258px;padding:5px;background:#252523;border-radius:25px;border:1px solid #252523;line-height:0;overflow:hidden}.phone img{width:100%;height:auto;aspect-ratio:390/844;border-radius:20px;display:block;background:white}.caption{padding:14px 0}.caption p{font-size:13px;margin:4px 0}.caption .links{display:flex;gap:16px}.links a{min-height:48px;display:inline-flex;align-items:center}.filename{font-size:12px;overflow-wrap:anywhere;color:#646461}.note{padding:16px 20px;border:1px solid #e2e2e0;border-radius:16px;background:white;margin:24px 0}.note p{margin:0}footer{border-top:1px solid #e2e2e0;padding-top:24px;padding-bottom:48px;font-size:13px}@media(max-width:1000px){.grid{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:750px){header,main,footer{padding-left:20px;padding-right:20px}.grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:24px 16px}h1{font-size:30px}}@media(max-width:420px){.grid{grid-template-columns:1fr}.phone{max-width:290px}figure{display:flex;flex-direction:column;align-items:center}.caption{width:290px;max-width:100%}}'''
def fig(v):
 name=v['name'];title=v['label'];theme='Koyu' if v.get('dark') else 'Açık'
 return '<figure><a class="phone" href="'+name+'.html" aria-label="'+escape(title+' · '+theme+' · HTML görünümü')+'"><img src="../_shots/B-'+name+'.png" width="780" height="1688" alt="'+escape(v['group']+' · '+title+' · '+theme)+'"></a><figcaption class="caption"><h3>'+escape(title)+'</h3><p>'+theme+' tema · 390 × 844</p><div class="filename">'+name+'.html</div><div class="links"><a href="'+name+'.html">HTML’yi aç</a><a href="../_shots/B-'+name+'.png">PNG’yi aç</a></div></figcaption></figure>'
html='<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>B · Ekran kataloğu — NGS Plus</title><style>'+css+'</style></head><body><header><div class="eyebrow">NGS Plus · B — Marka bandı</div><h1>Uygulama için ekran kataloğu</h1><p>Girişten ziyaretçi davetine kadar ortak bir mobil dil. Bordo bant yalnız kimlik veren ekranlarda; diğer ekranlarda nötr yüzeyler, net başlıklar ve tek birincil eylem.</p><div class="facts"><span>51 yeni görünüm</span><span>4 korunmuş yön referansı</span><span>390 × 844 · DPR 2</span><span>15 yeni koyu görünüm</span></div><p><a href="../../DESIGN_B.md">Uygulama sözleşmesi</a> · <a href="GAPS.md">Uygulama notları ve eksikler</a> · <a href="validation.json">Ölçüm sonuçları</a></p><nav aria-label="Ekran grupları">'+''.join('<a href="#group-'+str(i)+'">'+escape(g)+'</a>' for i,g in enumerate(groups))+'<a href="#reference">Önceki yön referansları</a></nav><div class="note"><p>D2/D3 hedefleri aşağıdaki yeni görünümlerdir. Telefon görseli PNG önizlemesidir; HTML bağlantısı kaydırılabilen asıl taslağı açar. Form, kamera ve klavye örnekleri statiktir; işlem göndermez. Yıldızlı ailelerin bütün istenen durumları koyu temada da gösterildiğinden toplam 51 yeni görünüm vardır.</p></div></header><main>'
notes={'Açılış':'Başlangıç durumu ve bağlantı hatasında güvenli sonraki adım.','Giriş':'Boş alanlar, kapalı mobil erişim ve giriş sürerken korunan form.','Şifre yardımı':'Kopyalanabilir yönetici talebi; e-posta gönderilmiş gibi sunulmaz.','Ana Sayfa':'Bugün kartı iskeleti, veri alınamayan durum ve bugün henüz kayıt yok.','QR':'Tara modu, kalıcı kamera izni reddi ve süresi dolan kod. Kamera sahnesi yerel SVG/CSS çizimidir.','Kapı işlemleri':'Kapı seçimi ve belirsiz işlemin aynı istekle güvenli kurtarılması.','Geçmiş':'Takvim, dönem özeti, boş liste ve ilgili ekran üzerindeki filtre/ayrıntı sheet’leri.','Talepler':'İzin ve kayıt düzeltme listeleri; boş görünüm, formlar, alan hatası ve geri çekme onayı.','Talep formları':'İzin formu, alan hatası, kayıt düzeltme formu ve geri çekme onayı.','Ziyaretçi formu':'Dolu form ve klavye üzerinde sabit kaydetme eylemi; açık ve koyu tema.','Ziyaretçi ayrıntısı':'İlgili liste üzerindeki ayrıntı sheet’i ve iptal onayı.','Ziyaretçiler':'Davet listesi, boş/hata durumu, form, klavye üstünde sabit eylem, ayrıntı ve iptal.','Profil':'Gruplu hesap tercihleri ve ilgili ekranın üzerinde tema seçimi.'}
for i,(g,vs) in enumerate(groups.items()):
 html+='<section class="group" id="group-'+str(i)+'"><h2>'+escape(g)+'</h2><p>'+str(len(vs))+' görünüm · '+escape(notes.get(g,''))+'</p><div class="grid">'+''.join(fig(v) for v in vs)+'</div></section>'
refs=[dict(name='home',label='Ana Sayfa · dolu',group='Yön referansı'),dict(name='history',label='Geçmiş · kayıtlar',group='Yön referansı'),dict(name='qr',label='QR Kodum · geçerli',group='Yön referansı'),dict(name='home-dark',label='Ana Sayfa · dolu',group='Yön referansı',dark=True)]
html+='<section class="group" id="reference"><h2>Önceki yön referansları</h2><p>Bu dört HTML ve PNG değiştirilmedi. W3 yön seçimi örnekleridir; 25px başlık/kompakt satır gibi eski ölçüler üretim hedefi değildir. Çelişkide DESIGN_B ve yukarıdaki yeni kit ölçüleri uygulanır.</p><div class="grid">'+''.join(fig(v) for v in refs)+'</div></section></main><footer>4 Kasım 2026 · Örnek kişi: Ayşe Yılmaz · NGS Teknoloji — Merkez. Tüm saatler Türkiye saatidir. Mobil kod bu mockup çalışmasında değiştirilmedi.</footer></body></html>'
(root/'index.html').write_text(html)
print('Catalog: '+str(len(manifest['newViews'])+len(refs))+' screen previews')
